358	  const { polls } = await request<{ polls: PollSummary[] }>("/api/polls");
359	  document.querySelector("#poll-count")!.textContent = `${polls.length} 个议题${isAdmin() ? "（含草稿）" : ""}`;
360	  list.replaceChildren();
