405	  const idInput = field("议题 id（slug，唯一）", Object.assign(document.createElement("input"), { type: "text", placeholder: "例如 community-tea-house" })) as HTMLInputElement;
406	  const titleInput = field("标题", Object.assign(document.createElement("input"), { type: "text" })) as HTMLInputElement;
407	  const organizerInput = field("组织方", Object.assign(document.createElement("input"), { type: "text" })) as HTMLInputElement;
