422	    const idInputOption = document.createElement("input"); idInputOption.placeholder = "选项 id"; idInputOption.value = id;
423	    const labelInputOption = document.createElement("input"); labelInputOption.placeholder = "选项文案"; labelInputOption.value = label;
424	    const remove = document.createElement("button"); remove.type = "button"; remove.className = "admin-button ghost"; remove.textContent = "删";
425	    remove.addEventListener("click", () => { rowDiv.remove(); optionRows.splice(optionRows.findIndex(entry => entry.id === idInputOption), 1); });
426	    rowDiv.append(idInputOption, labelInputOption, remove);
427	    optionsMount.append(rowDiv);
