447	      closesAt: new Date(closesInput.value).toISOString(),
448	      options: optionRows.map(row => ({ id: row.id.value.trim(), label: row.label.value.trim() })),
449	      commitments: commitmentsInput.value.split("\n").map(value => value.trim()).filter(Boolean)
450	    };
451	    submit.disabled = true;
452	    try {
453	      const { poll } = await request<{ poll: PollDetail }>("/api/polls", {
454	        method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload)
455	      });
456	      line.textContent = `已创建草稿 ${poll.id}（201）。`;
457	      line.className = "create-status ok";
458	      modalRoot.replaceChildren();
