15	  description: string;
16	  options: PollOption[];
17	  eligibleMemberCommitments: string[];
18	  groupVersion: number;
19	  merkleRoot: string;
20	}
21	export interface GroupVersionSummary {
22	  pollId: string;
23	  version: number;
24	  merkleRoot: string;
25	  memberCount: number;
