      const tr = document.createElement("tr");
      tr.append(htmlCell("td", dateTime(event.at)));
      tr.append(htmlCell("td", ACTION_LABEL[event.action] ?? event.action));
      tr.append(htmlCell("td", event.pollId, "mono"));
